<?php
declare(strict_types=1);session_start();require_once __DIR__.'/config/finance_step16.php';if(empty($_SESSION['fr_csrf']))$_SESSION['fr_csrf']=bin2hex(random_bytes(24));$csrf=(string)$_SESSION['fr_csrf'];$error=null;$success=null;$accounts=[];$pending=[];$journalLines=[];$recs=[];$selected=(int)($_GET['account']??$_POST['cash_account_id']??0);
try{$pdo=business_db();finance_step16_ensure($pdo);finance_step16_sync_all($pdo);$ctx=finance_step16_context($pdo);$orgId=(int)$ctx['organization_id'];if($_SERVER['REQUEST_METHOD']==='POST'){if(!hash_equals($csrf,(string)($_POST['csrf']??'')))throw new RuntimeException('Security token mismatch.');$action=(string)($_POST['action']??'');if($action==='statement'){$id=finance_step16_add_statement_line($pdo,(int)$_POST['cash_account_id'],(string)$_POST['statement_date'],(float)$_POST['amount_signed'],(string)($_POST['description']??''),(string)($_POST['reference_no']??''));$success='Statement line #'.$id.' added.';}elseif($action==='match'){finance_step16_match_statement($pdo,(int)$_POST['statement_id'],(int)$_POST['journal_line_id']);$success='Statement line matched to cashbook.';}elseif($action==='reconcile'){$id=finance_step16_create_reconciliation($pdo,(int)$_POST['cash_account_id'],(string)$_POST['period_start'],(string)$_POST['period_end'],(float)$_POST['statement_ending_balance'],(string)($_POST['notes']??''));$success='Reconciliation #'.$id.' created.';}}$accounts=finance_step16_accounts($pdo,$orgId);if($selected<=0&&$accounts)$selected=(int)$accounts[0]['id'];if($selected>0){finance_step16_cash($pdo,$orgId,$selected);$stmt=$pdo->prepare("SELECT * FROM finance_statement_lines WHERE organization_id=? AND cash_account_id=? ORDER BY statement_date DESC,id DESC LIMIT 120");$stmt->execute([$orgId,$selected]);$pending=$stmt->fetchAll();$stmt=$pdo->prepare("SELECT l.id,j.journal_date,j.journal_number,j.memo,l.debit_amount,l.credit_amount,(l.debit_amount-l.credit_amount) movement FROM finance_journal_lines l JOIN finance_journals j ON j.id=l.journal_id AND j.organization_id=l.organization_id WHERE l.organization_id=? AND l.cash_account_id=? ORDER BY j.journal_date DESC,l.id DESC LIMIT 160");$stmt->execute([$orgId,$selected]);$journalLines=$stmt->fetchAll();$stmt=$pdo->prepare("SELECT * FROM finance_reconciliations WHERE organization_id=? AND cash_account_id=? ORDER BY period_end DESC,id DESC LIMIT 40");$stmt->execute([$orgId,$selected]);$recs=$stmt->fetchAll();}}catch(Throwable $e){$error=$e->getMessage();}
function fr_h(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}function fr_m(mixed $v):string{return '₹'.number_format((float)$v,2,'.',',');}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Finance Reconciliation - Healthcare Wellness Club</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/product_pro.css"></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="finance_center.php"><img src="../img/logo.png" alt="logo"><span><strong>Healthcare Wellness Club</strong><small>STEP 16 • Reconciliation</small></span></a><div class="os-top-actions"><a class="os-btn" href="finance_cashbook.php">Cashbook</a><a class="os-btn" href="finance_accounts.php">Accounts</a><a class="os-btn primary" href="finance_center.php">Finance Center</a></div></div></header><div class="os-layout"><aside class="os-sidebar"><div class="os-nav-label">Finance</div><nav class="os-nav"><a href="finance_center.php"><i class="dot"></i>Finance Center</a><a href="finance_cashbook.php"><i class="dot"></i>Cashbook</a><a class="active" href="finance_reconciliation.php"><i class="dot"></i>Reconciliation</a><a href="finance_journal.php"><i class="dot"></i>Journal</a></nav></aside><main class="os-main"><section class="os-hero pp-hero"><div class="os-kicker">STEP 16H • RECONCILIATION</div><h1>Match statement movements to the cashbook and confirm closing balance.</h1><p>Positive statement amount means money in; negative means money out. Exact amount matching prevents accidental reconciliation to the wrong journal line.</p></section><?php if($error):?><div class="pp-alert bad"><strong>Reconciliation diagnostic:</strong> <?= fr_h($error) ?></div><?php endif;?><?php if($success):?><div class="pp-alert good"><strong>Done:</strong> <?= fr_h($success) ?></div><?php endif;?><?php if(!$error):?><section class="os-card" style="margin-top:14px"><form method="get" class="pp-form"><label>Account<select name="account"><?php foreach($accounts as $a):?><option value="<?= (int)$a['id'] ?>" <?= $selected===(int)$a['id']?'selected':'' ?>><?= fr_h($a['account_name'].($a['is_system_clearing']?' • Clearing':'')) ?></option><?php endforeach;?></select></label><button>Open Account</button></form></section><section class="pp-grid" style="margin-top:14px"><article class="os-card pp-span-6"><h2>Add Statement Line</h2><form method="post" class="pp-form"><input type="hidden" name="csrf" value="<?= fr_h($csrf) ?>"><input type="hidden" name="action" value="statement"><input type="hidden" name="cash_account_id" value="<?= $selected ?>"><label>Date<input type="date" name="statement_date" value="<?= date('Y-m-d') ?>" required></label><label>Amount (+ in / − out)<input type="number" step="0.01" name="amount_signed" required></label><label>Description<input name="description"></label><label>Reference<input name="reference_no"></label><button>Add Statement Line →</button></form></article><article class="os-card pp-span-6"><h2>Close Reconciliation Period</h2><form method="post" class="pp-form"><input type="hidden" name="csrf" value="<?= fr_h($csrf) ?>"><input type="hidden" name="action" value="reconcile"><input type="hidden" name="cash_account_id" value="<?= $selected ?>"><label>Period Start<input type="date" name="period_start" value="<?= date('Y-m-01') ?>" required></label><label>Period End<input type="date" name="period_end" value="<?= date('Y-m-t') ?>" required></label><label>Statement Ending Balance<input type="number" step="0.01" name="statement_ending_balance" required></label><label>Notes<input name="notes"></label><button>Calculate & Reconcile →</button></form></article></section><section class="os-card" style="margin-top:14px"><h2>Statement Lines</h2><div class="pp-table-wrap"><table class="pp-table"><thead><tr><th>Date</th><th>Amount</th><th>Description</th><th>Status</th><th>Match Cashbook Movement</th></tr></thead><tbody><?php foreach($pending as $s):?><tr><td><?= fr_h($s['statement_date']) ?></td><td><b><?= fr_m($s['amount_signed']) ?></b></td><td><?= fr_h($s['description']?:'—') ?><small><?= fr_h($s['reference_no']?:'') ?></small></td><td><span class="pp-badge <?= $s['status']==='matched'?'':'warn' ?>"><?= fr_h(strtoupper($s['status'])) ?></span></td><td><?php if($s['status']==='pending'):?><form method="post" class="pp-form"><input type="hidden" name="csrf" value="<?= fr_h($csrf) ?>"><input type="hidden" name="action" value="match"><input type="hidden" name="statement_id" value="<?= (int)$s['id'] ?>"><select name="journal_line_id" required><option value="">Choose exact amount…</option><?php foreach($journalLines as $j):?><?php if(abs((float)$j['movement']-(float)$s['amount_signed'])>0.01)continue;?><option value="<?= (int)$j['id'] ?>"><?= fr_h($j['journal_date'].' • '.$j['journal_number'].' • '.fr_m($j['movement']).' • '.($j['memo']?:'')) ?></option><?php endforeach;?></select><button>Match</button></form><?php else:?>Journal line #<?= (int)$s['matched_journal_line_id'] ?><?php endif;?></td></tr><?php endforeach;?><?php if(!$pending):?><tr><td colspan="5">No statement lines yet.</td></tr><?php endif;?></tbody></table></div></section><section class="os-card" style="margin-top:14px"><h2>Reconciliation History</h2><div class="pp-table-wrap"><table class="pp-table"><thead><tr><th>Period</th><th>Statement Ending</th><th>Calculated Ending</th><th>Difference</th><th>Status</th></tr></thead><tbody><?php foreach($recs as $r):?><tr><td><?= fr_h($r['period_start'].' → '.$r['period_end']) ?></td><td><?= fr_m($r['statement_ending_balance']) ?></td><td><?= fr_m($r['calculated_ending_balance']) ?></td><td><b><?= fr_m($r['difference_amount']) ?></b></td><td><span class="pp-badge <?= $r['status']==='reconciled'?'':'warn' ?>"><?= fr_h(strtoupper($r['status'])) ?></span></td></tr><?php endforeach;?><?php if(!$recs):?><tr><td colspan="5">No reconciliation periods yet.</td></tr><?php endif;?></tbody></table></div></section><div class="os-footer-note"><strong>Reconciliation rule:</strong> a period is marked RECONCILED only when statement ending balance and calculated cashbook balance differ by no more than ₹0.01.</div><?php endif;?></main></div></body></html>